// Remote exec helper for server .215 — mirrors /opt/nxeon/lib/sftp.ts + ssh-exec.ts.
// Fetches the server record from the Nxeon DB, decrypts rootPasswordEnc, and runs
// a command (from argv[2] or stdin) over ssh2, never echoing the password.
require("dotenv").config({ path: "/opt/nxeon/.env" });
const { Client } = require("ssh2");
const { scryptSync, createDecipheriv } = require("node:crypto");
const { PrismaClient } = require("@prisma/client");

const SERVER_ID = "cmsecmdps0001hlp27ai6mr7c";

function decryptSecret(enc) {
  if (!enc) return null;
  try {
    const key = scryptSync(process.env.AUTH_SECRET, "nxeon-byok", 32);
    const [ivB64, tagB64, dataB64] = enc.split(":");
    if (!ivB64 || !tagB64 || !dataB64) return null;
    const d = createDecipheriv("aes-256-gcm", key, Buffer.from(ivB64, "base64"));
    d.setAuthTag(Buffer.from(tagB64, "base64"));
    return Buffer.concat([d.update(Buffer.from(dataB64, "base64")), d.final()]).toString("utf8");
  } catch { return null; }
}

async function main() {
  const db = new PrismaClient();
  const server = await db.server.findUnique({
    where: { id: SERVER_ID },
    include: { dedicatedIp: true },
  });
  await db.$disconnect();
  if (!server) throw new Error("server not found");
  const pw = decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
  if (!pw) throw new Error("no root password");
  const dedicated = !!server.dedicatedIp;
  const host = dedicated ? server.dedicatedIp.address : process.env.PUBLIC_IP;
  const port = dedicated ? 22 : server.sshPort;
  process.stderr.write(`[rexec] target host=${host} port=${port}\n`);

  let cmd = process.argv[2];
  if (cmd === "-") cmd = require("node:fs").readFileSync(0, "utf8");
  if (!cmd) throw new Error("no command");

  const conn = new Client();
  await new Promise((resolve, reject) => {
    conn.on("ready", resolve).on("error", reject).connect({
      host, port, username: "root", password: pw, readyTimeout: 20000,
    });
  });
  const result = await new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream) => {
      if (err) return reject(err);
      let out = "", erro = "";
      stream.on("close", (code) => resolve({ code, out, erro }))
        .on("data", (d) => (out += d.toString("utf8")))
        .stderr.on("data", (d) => (erro += d.toString("utf8")));
    });
  });
  conn.end();
  process.stdout.write(result.out);
  if (result.erro) process.stderr.write("[stderr]\n" + result.erro);
  process.exit(result.code === 0 ? 0 : (result.code ?? 1));
}
main().catch((e) => { console.error("[rexec] " + e.message); process.exit(1); });

