const META_BY_KEY: Record<TemplateKey, TemplateMeta> = Object.fromEntries(
  TEMPLATE_META.map((m) => [m.key, m]),
) as Record<TemplateKey, TemplateMeta>;

export const DEFAULT_TEMPLATES: Record<TemplateKey, EmailTemplate> = Object.fromEntries(
  TEMPLATE_META.map((m) => [m.key, m.default]),
) as Record<TemplateKey, EmailTemplate>;

export function isTemplateKey(k: string): k is TemplateKey {
  return k in META_BY_KEY;
}

export function templateMeta(key: TemplateKey): TemplateMeta {
  return META_BY_KEY[key];
}

/** Sample values keyed by placeholder token — drives the live preview. */
export function sampleVarsFor(key: TemplateKey): Record<string, string> {
  return Object.fromEntries(META_BY_KEY[key].vars.map((v) => [v.token, v.sample]));
}

type Store = { emailTemplates?: Partial<Record<TemplateKey, EmailTemplate>> };

/** The effective template for a studio: its override merged over the default. */
export function getTemplate(tenant: Pick<Tenant, "policies">, key: TemplateKey): EmailTemplate {
  const saved = ((tenant.policies ?? {}) as Store).emailTemplates?.[key];
  return { ...DEFAULT_TEMPLATES[key], ...(saved ?? {}) };
}

/** True when the studio has customised this template (i.e. reset would change it). */
export function hasOverride(tenant: Pick<Tenant, "policies">, key: TemplateKey): boolean {
  return !!((tenant.policies ?? {}) as Store).emailTemplates?.[key];
}

/** Substitute {{token}} placeholders in subject + body. Unknown tokens → "". */
export function renderTemplate(tpl: EmailTemplate, vars: Record<string, string | number>): EmailTemplate {
  const fill = (s: string) => s.replace(/\{\{(\w+)\}\}/g, (_, k) => (vars[k] !== undefined ? String(vars[k]) : ""));
  return { subject: fill(tpl.subject), body: fill(tpl.body) };
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

// Turn a plain-text body into simple HTML: links become anchors, newlines
// become <br>, blank lines separate paragraphs. Kept deliberately small — this
// is a transactional email, not a newsletter.
function bodyToHtml(body: string): string {
  const linkify = (line: string) =>
    escapeHtml(line).replace(
      /(https?:\/\/[^\s<]+)/g,
      (url) => `<a href="${url}" style="color:#2563eb;text-decoration:underline;">${url}</a>`,
    );
  return body
    .split(/\n{2,}/)
    .map((para) => `<p style="margin:0 0 16px;">${para.split("\n").map(linkify).join("<br>")}</p>`)
    .join("");
}

export type Branding = { name: string; logoUrl?: string | null; brandColor?: string | null };

/**
 * Wrap a rendered plain-text body in a branded, email-client-safe HTML shell
 * carrying the studio logo (or its name) and brand-colour accent. `logoUrl`
 * should already be absolute — see absoluteLogoUrl().
 */
export function renderBrandedHtml(brand: Branding, bodyText: string): string {
  const accent = /^#[0-9a-fA-F]{6}$/.test(brand.brandColor ?? "") ? brand.brandColor! : "#F97316";
  const header = brand.logoUrl
    ? `<img src="${escapeHtml(brand.logoUrl)}" alt="${escapeHtml(brand.name)}" style="max-height:48px;max-width:220px;display:block;margin:0 auto;">`
    : `<div style="font-size:20px;font-weight:800;color:${accent};text-align:center;letter-spacing:-0.01em;">${escapeHtml(brand.name)}</div>`;
  return [
    `<!doctype html><html><body style="margin:0;padding:0;background:#f4f4f5;">`,
    `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5;padding:24px 0;">`,
    `<tr><td align="center">`,
    `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #e4e4e7;">`,
    `<tr><td style="height:4px;background:${accent};font-size:0;line-height:0;">&nbsp;</td></tr>`,
    `<tr><td style="padding:28px 32px 8px;">${header}</td></tr>`,
    `<tr><td style="padding:8px 32px 28px;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.6;color:#27272a;">`,
    bodyToHtml(bodyText),
    `</td></tr>`,
    `<tr><td style="padding:16px 32px 24px;border-top:1px solid #f0f0f1;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:12px;color:#a1a1aa;text-align:center;">Sent by ${escapeHtml(brand.name)}</td></tr>`,
    `</table></td></tr></table></body></html>`,
  ].join("");
}

/** Resolve the studio logo to an absolute URL usable inside an email. */
export function absoluteLogoUrl(
  tenant: Pick<Tenant, "logoUrl" | "slug" | "customDomain" | "policies">,
): string | null {
  if (!tenant.logoUrl) return null;
  if (/^https?:\/\//.test(tenant.logoUrl)) return tenant.logoUrl;
  return `${publicSiteUrl(tenant)}${tenant.logoUrl.startsWith("/") ? "" : "/"}${tenant.logoUrl}`;
}

/**
 * One-stop builder for a send path: resolve the studio's effective template,
 * substitute variables, and produce the plain-text body plus the branded HTML
 * (with logo) for delivery. `body` is the plain-text version stored in EmailLog.
 */
export function buildEmail(
  tenant: Pick<Tenant, "policies" | "name" | "logoUrl" | "slug" | "customDomain" | "brandColor">,
  key: TemplateKey,
  vars: Record<string, string | number>,
): { subject: string; body: string; html: string } {
  const rendered = renderTemplate(getTemplate(tenant, key), vars);
  const html = renderBrandedHtml(
    { name: tenant.name, logoUrl: absoluteLogoUrl(tenant), brandColor: tenant.brandColor },
    rendered.body,
  );
  return { subject: rendered.subject, body: rendered.body, html };
}

import nodemailer from "nodemailer";
import { db } from "@/lib/db";
import { BASE_DOMAIN } from "@/lib/config";

// SMTP is optional. Without SMTP_HOST every send is recorded in EmailLog
// as "skipped" so the product behaves identically and flipping on real
// email later is just env vars + restart.
function transport() {
  if (!process.env.SMTP_HOST) return null;
  return nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: Number(process.env.SMTP_PORT ?? 587),
    secure: process.env.SMTP_SECURE === "true",
    auth: process.env.SMTP_USER ? { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS } : undefined,
  });
}

// `html` is optional: when a send path provides a branded HTML version (see
// lib/email-templates.buildEmail) it is delivered as the rich part with `body`
// as the plain-text fallback. EmailLog only ever stores the plain-text `body`.
export async function sendEmail(opts: { tenantId: string; to: string; subject: string; body: string; html?: string }) {
  const t = transport();
  let status = "skipped";
  if (t) {
    try {
      await t.sendMail({
        from: process.env.SMTP_FROM ?? `no-reply@${BASE_DOMAIN}`,
        to: opts.to,
        subject: opts.subject,
        text: opts.body,
        ...(opts.html ? { html: opts.html } : {}),
      });
      status = "sent";
    } catch {
      status = "failed";
    }
  }
  await db.emailLog.create({
    data: { tenantId: opts.tenantId, to: opts.to, subject: opts.subject, body: opts.body, status },
  });
  return status;
}

import { createHash } from "crypto";
import type { Tenant, User } from "@prisma/client";
import { sendEmail } from "@/lib/mailer";
import { sendSms } from "@/lib/sms";
import { buildEmail } from "@/lib/email-templates";

// Login verification (2FA). Safe by design: it only ever engages when the
// studio has it enabled AND a delivery channel is actually configured for the
// signing-in user — otherwise login stays password-only (nobody is locked out).
export const CODE_TTL_MIN = 10;

export type Channel = "email" | "sms";
export type SecurityPolicy = { loginVerification?: "off" | "email" | "sms" | "any" };

export function securityOf(tenant: Pick<Tenant, "policies">): SecurityPolicy {
  return (((tenant.policies ?? {}) as { security?: SecurityPolicy }).security) ?? {};
}

const smtpLive = () => !!process.env.SMTP_HOST;
const twilioLive = () => !!process.env.TWILIO_ACCOUNT_SID;

// The channel we can actually deliver on for this user, honouring the studio's
// preference. Returns null when nothing is deliverable (→ password-only).
export function liveChannelFor(tenant: Pick<Tenant, "policies">, user: Pick<User, "email" | "phone">): { channel: Channel; contact: string } | null {
  const pref = securityOf(tenant).loginVerification ?? "any";
  if (pref === "off") return null;
  const canEmail = smtpLive() && !!user.email;
  const canSms = twilioLive() && !!user.phone;
  if (pref === "email") return canEmail ? { channel: "email", contact: user.email! } : null;
  if (pref === "sms") return canSms ? { channel: "sms", contact: user.phone! } : null;
  // "any": prefer email, fall back to SMS
  if (canEmail) return { channel: "email", contact: user.email! };
  if (canSms) return { channel: "sms", contact: user.phone! };
  return null;
}

export function generateCode(): string {
  return String(Math.floor(100000 + Math.random() * 900000));
}
export function hashCode(code: string): string {
  return createHash("sha256").update(`${code}:${process.env.AUTH_SECRET ?? ""}`).digest("hex");
}

export async function sendLoginCode(tenant: Tenant, user: Pick<User, "name">, channel: Channel, contact: string, code: string) {
  if (channel === "email") {
    const mail = buildEmail(tenant, "loginCode", { studio: tenant.name, name: user.name, code, minutes: CODE_TTL_MIN });
    await sendEmail({ tenantId: tenant.id, to: contact, subject: mail.subject, body: mail.body, html: mail.html });
  } else {
    await sendSms({ tenantId: tenant.id, to: contact, kind: "verification", body: `${tenant.name}: your verification code is ${code}. Expires in ${CODE_TTL_MIN} min.` });
  }
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { sendEmail } from "@/lib/mailer";
import { sendSms } from "@/lib/sms";
import { timeInTz } from "@/lib/tz";
import { publicSiteUrl } from "@/lib/site-url";
import { buildEmail } from "@/lib/email-templates";

// Hit hourly by system cron with the shared secret. Emails clients whose
// class starts within the next 24h and hasn't been reminded yet.
export async function POST(req: Request) {
  if (new URL(req.url).searchParams.get("token") !== process.env.CRON_TOKEN) {
    return NextResponse.json({ error: "forbidden" }, { status: 403 });
  }

  const due = await db.booking.findMany({
    where: {
      status: "BOOKED",
      remindedAt: null,
      client: { OR: [{ email: { not: null } }, { phone: { not: null } }] },
      session: { startsAt: { gt: new Date(), lt: new Date(Date.now() + 24 * 3600_000) }, status: "SCHEDULED" },
    },
    include: { client: true, session: { include: { classType: true } }, tenant: true },
    take: 200,
  });

  let sent = 0;
  for (const b of due) {
    if (!b.client.email && b.client.phone) {
      await sendSms({
        tenantId: b.tenantId,
        to: b.client.phone,
        kind: "reminder",
        body: `${b.tenant.name}: reminder — ${b.session.classType.name} ${b.session.startsAt.toLocaleDateString("en-US", { timeZone: b.tenant.timezone, weekday: "short", month: "short", day: "numeric" })} at ${timeInTz(b.session.startsAt, b.tenant.timezone)}.`,
      });
      await db.booking.update({ where: { id: b.id }, data: { remindedAt: new Date() } });
      sent++;
      continue;
    }
    const dateTime = `${b.session.startsAt.toLocaleDateString("en-US", { timeZone: b.tenant.timezone, weekday: "long", month: "long", day: "numeric" })} at ${timeInTz(b.session.startsAt, b.tenant.timezone)}`;
    const mail = buildEmail(b.tenant, "reminder", {
      studioName: b.tenant.name,
      studio: b.tenant.name,
      clientName: b.client.name,
      name: b.client.name,
      className: b.session.classType.name,
      dateTime,
      manageUrl: publicSiteUrl(b.tenant, "/bookings"),
    });
    await sendEmail({ tenantId: b.tenantId, to: b.client.email!, subject: mail.subject, body: mail.body, html: mail.html });
    await db.booking.update({ where: { id: b.id }, data: { remindedAt: new Date() } });
    sent++;
  }
  return NextResponse.json({ ok: true, reminded: sent });
}

